args.content:
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX schema: <http://schema.org/>

SELECT ?item ?itemLabel ?coord
WHERE {
  ?item wdt:P31 wd:Q4766192;  # point of interest
        wdt:P625 ?coord .
  FILTER(?item NOT IN wd:Q8813)  # Exclude the city itself
  OPTIONAL {
    ?item schema:containedInPlace wd:Q8813 .  # Alicante
  }
  OPTIONAL {
    ?item schema:containedInPlace wd:Q29 .  # Spain
  }
  SERVICE wikibase:label {
    bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" .
  }
}

